                ['icon' => 'search', 'title' => 'Prepares you for an MSc application', 'text' => 'Research methods and a proposal-writing focus are exactly what postgraduate admissions tutors look for in a converting applicant.'],
                ['icon' => 'triangle-alert', 'title' => 'Know the limit before you enrol', 'text' => 'It does not make you a practising psychologist anywhere, including in the GCC. Check your country\'s licensing body about what registration actually requires.'],
