            'gcc_heading' => 'Why Process Industries in the Gulf Look Here',
            'gcc' => [
                ['icon' => 'factory', 'title' => 'The region runs on process plant', 'text' => 'Refining, petrochemicals, gas processing and fertiliser production are core GCC industries, and this is their safety discipline.'],
                ['icon' => 'clipboard-list', 'title' => 'HAZOP is already the local language', 'text' => 'Hazard and operability study is standard practice on regional plant, so the content matches the work.'],
