            'gcc_heading' => 'Why Data Roles in the Gulf Are Growing Fast',
            'gcc' => [
                ['icon' => 'database', 'title' => 'National data strategies are live', 'text' => 'Government programmes across the region are building analytics capability inside public bodies.'],
